mapper.select:
SELECT DATE(t1.inout_time) AS day, sum(if(inout_type = 'IN',inout_amount,0)) AS inAmount, sum(if(inout_type = 'OUT',inout_amount,0)) AS outAmount, (SELECT SUM(t2.inout_amount) FROM emergency_fund_inout_record t2 WHERE DATE(t2.inout_time) <= DATE(t1.inout_time) and t2.inout_type = 'IN') AS inAmountTotal, (SELECT SUM(t2.inout_amount) FROM emergency_fund_inout_record t2 WHERE DATE(t2.inout_time) <= DATE(t1.inout_time) and t2.inout_type = 'OUT') AS outAmountTotal FROM emergency_fund_inout_record t1
and t1.inout_time >= #{param.period.begin}
and t1.inout_time <= #{param.period.end}
GROUP BY day

select DATE_FORMAT(inout_time,#{param.groupFormat}) as day, sum(if(inout_type = 'IN',inout_amount,0)) AS inAmount, sum(if(inout_type = 'OUT',inout_amount,0)) AS outAmount from emergency_fund_inout_record
and inout_time >= #{param.period.begin}
and inout_time <= #{param.period.end}
group by day
